#include <string>
#include <vector>
#include <cstring>

class Solution {
public:
    int countGoodIntegersInRange(int low, int high, int k) {
        auto countUpTo = [&](int limit) -> int {
            if (limit < 0) return 0;
            std::string s = std::to_string(limit);
            int n = s.size();
            int memo[20][50][2];
            std::memset(memo, -1, sizeof(memo));
            auto dp = [&](auto self, int idx, int rem, bool isLess) -> int {
                if (idx == n) return rem == 0 ? 1 : 0;
                if (memo[idx][rem][isLess] != -1) return memo[idx][rem][isLess];
                int ub = isLess ? 9 : (s[idx] - '0');
                int total = 0;
                for (int d = 0; d <= ub; ++d) {
                    total += self(self, idx + 1, (rem + d) % k, isLess || (d < ub));
                }
                return memo[idx][rem][isLess] = total;
            };
            return dp(dp, 0, 0, false);
        };
        return countUpTo(high) - countUpTo(low - 1);
    }
};

import java.util.*;

class Solution {
    public int countGoodIntegersInRange(int low, int high, int k) {
        return countUpTo(high, k) - countUpTo(low - 1, k);
    }

    private int countUpTo(int limit, int k) {
        if (limit < 0) return 0;
        String s = Integer.toString(limit);
        int[][][] memo = new int[s.length()][k][2];
        for (int[][] a : memo) for (int[] b : a) Arrays.fill(b, -1);
        return solve(0, 0, 0, s, k, memo);
    }

    private int solve(int idx, int rem, int isLess, String s, int k, int[][][] memo) {
        if (idx == s.length()) return rem == 0 ? 1 : 0;
        if (memo[idx][rem][isLess] != -1) return memo[idx][rem][isLess];
        int ub = (isLess == 1) ? 9 : (s.charAt(idx) - '0');
        int total = 0;
        for (int d = 0; d <= ub; d++) {
            total += solve(idx + 1, (rem + d) % k, (isLess == 1 || d < ub) ? 1 : 0, s, k, memo);
        }
        return memo[idx][rem][isLess] = total;
    }
}

