        function dp(idx, rem, isLess) {
            if (idx === s.length) return rem === 0 ? 1 : 0;
            const key = `${idx}_${rem}_${isLess}`;
            if (memo.has(key)) return memo.get(key);
            const ub = isLess ? 9 : Number(s[idx]);
            let total = 0;
            for (let d = 0; d <= ub; d++) {
                total += dp(idx + 1, (rem + d) % k, isLess || d < ub);
            }
            memo.set(key, total);
            return total;
        }
        return dp(0, 0, false);
    }
    return countUpTo(high) - countUpTo(low - 1);
